{"content":""""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.

Profiles are tenant-authored, so values are parsed with ``ast.literal_eval`` rather than
``eval``: ``literal_eval`` accepts literals and literal containers (numbers, strings, lists,
dicts, tuples, sets, ``None``/``True``/``False``) but never executes code. Plugin selection
goes through the ``plugins.BUILTIN_PLUGINS`` registry rather than a dynamic import, so a
profile can only name transforms we have explicitly vetted.
"""

from __future__ import annotations

import ast

from plugins import BUILTIN_PLUGINS

__all__ = ["load_config"]

_PLUGIN_KEY = "plugin"


def _parse_value(key: str, raw_value: str, line_no: int) -> object:
    """Parse one profile value into a Python object.

    Only literal data is accepted; anything that would require evaluating code (calls,
    names, operators, comprehensions, ...) is rejected with a ``ValueError``.
    """
    try:
        return ast.literal_eval(raw_value)
    except (ValueError, SyntaxError, TypeError) as exc:
        raise ValueError(
            f"profile line {line_no}: cannot parse value for {key!r}: {raw_value!r}"
        ) from exc


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name from
    ``plugins.BUILTIN_PLUGINS`` (an instance, or ``None`` when the profile sets no
    plugin).
    """
    settings: dict = {}
    plugin = None

    for line_no, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        key, sep, raw_value = line.partition("=")
        if not sep:
            raise ValueError(
                f"profile line {line_no}: expected 'key = value', got {raw_line!r}"
            )
        key = key.strip()
        raw_value = raw_value.strip()
        if not key:
            raise ValueError(f"profile line {line_no}: missing key in {raw_line!r}")

        value = _parse_value(key, raw_value, line_no)

        if key == _PLUGIN_KEY:
            if not isinstance(value, str):
                raise ValueError(
                    f"profile line {line_no}: plugin name must be a string, got {value!r}"
                )
            try:
                plugin_cls = BUILTIN_PLUGINS[value]
            except KeyError:
                available = ", ".join(sorted(BUILTIN_PLUGINS)) or "(none)"
                raise ValueError(
                    f"profile line {line_no}: unknown plugin {value!r} "
                    f"(available: {available})"
                ) from None
            plugin = plugin_cls()
        else:
            settings[key] = value

    return {"settings": settings, "plugin": plugin}
